      flt_paperwork_one: "{{count}} ਵਾਹਨ ਦਾ ਕਾਗਜ਼ਾਂ (REGO / DG / eSCBA) 30 ਦਿਨ ਦੇ ਅੰਦਰ ਸਮਾਪਤ ਹੋ ਰਿਹਾ ਹੈ। ਮਿਆਦ ਤਾਰੀਖ ਤੋਂ ਪਹਿਲਾਂ ਡ੍ਰਾਈਵਰ ਨਾਲ ਪਿੱਛਾ-ਪਿੱਛੇ ਜਾਓ।",
      flt_paperwork_other: "{{count}} ਵਾਹਨ ਦੇ ਕਾਗਜ਼ਾਂ (REGO / DG / eSCBA) 30 ਦਿਨ ਦੇ ਅੰਦਰ ਸਮਾਪਤ ਹੋ ਰਹੇ ਹਨ। ਮਿਆਦ ਤਾਰੀਖ ਤੋਂ ਪਹਿਲਾਂ ਡ੍ਰਾਈਵਰ ਨਾਲ ਪਿੱਛਾ-ਪਿੱਛੇ ਜਾਓ।",
      flt_legend: "ਅੰਬਰ = 30 ਦਿਨ ਦੇ ਅੰਦਰ ਸਮਾਪਤ। ਲਾਲ = ਸਮਾਪਤ ਜਾਂ ਜ਼ਮੀਨੀ। ਡ੍ਰਾਈਵਰਾਂ ਨੂੰ ਉਹੀ ਮਿਆਦ ਬੈਜ ਉਹਨਾਂ ਦੇ ਵਾਹਨ ਟੈਬ ਵਿੱਚ ਦਿਖਦੇ ਹਨ।",
