      ivb_title: "ਪ੍ਰਵੇਸ਼ ਅੱਪਡੇਟ ਲਾਜ਼ਮੀ — ਵਰਜ਼ਨ {{version}}",
      ivb_message: "ਤੁਹਾਡੇ ਆਖਰੀ ਪੂਰਣ ਕਰਨ ਦੇ ਬਾਅਦ ਪ੍ਰਵੇਸ਼ ਸਮੱਗਰੀ ਅੱਪਡੇਟ ਹੋਈ ਹੈ (ਤੁਹਾਡਾ ਸਰਟੀਫਿਕੇਟ ਵਰਜ਼ਨ {{oldVersion}} ਅਧੀਨ ਜਾਰੀ ਹੋਇਆ ਸੀ)। ਅਨੁਪਾਲਨ ਬਣਾਏ ਰੱਖਣ ਲਈ ਤੁਹਾਨੂੰ ਪ੍ਰਵੇਸ਼ ਦੁਬਾਰਾ ਪੂਰਾ ਕਰਨਾ ਹੋਵੇਗਾ। ਆਪਣੇ ਮੈਨੇਜਰ ਨਾਲ ਸੰਪਰਕ ਕਰੋ ਜਾਂ ਹੋਰ ਹਦਾਇਤਾਂ ਨਾਲ ਈਮੇਲ ਸੂਚਨਾ ਦੀ ਉਡੀਕ ਕਰੋ।",
