      ivp_desc: "ਨਵਾਂ ਵਰਜ਼ਨ ਪ੍ਰਕਾਸ਼ਿਤ ਕਰਨ ਨਾਲ ਸਾਰੇ ਡ੍ਰਾਈਵਰਾਂ ਨੂੰ (ਅਗਲੀ ਲੌਗਿਨ ਉੱਤੇ) ਸੂਚਿਤ ਕੀਤਾ ਜਾਵੇਗਾ ਕਿ ਉਹਨਾਂ ਨੂੰ ਪ੍ਰਵੇਸ਼ ਦੁਬਾਰਾ ਪੂਰਾ ਕਰਨਾ ਹੈ। ਉਹਨਾਂ ਦੇ ਮੌਜੂਦਾ ਸਰਟੀਫਿਕੇਟ ਆਰਕਾਈਵ ਹੋ ਜਾਂਦੇ ਹਨ ਅਤੇ ਤਸਦੀਕਯੋਗ ਰਹਿੰਦੇ ਹਨ — ਸਿਰਫ਼ ਦੁਬਾਰਾ ਪ੍ਰਵੇਸ਼ ਹੀ ਨਵਾਂ ਸਰਟੀਫਿਕੇਟ ਜਾਰੀ ਕਰੇਗਾ।",
