const storedLang = window.localStorage.getItem("bnt-lang");

i18n
  .use(initReactI18next)
  .init({
    resources,
    lng: storedLang === "pa" ? "pa" : "en",
    fallbackLng: "en",
    interpolation: {
      escapeValue: false // react already safes from xss
    }
  });

document.documentElement.lang = i18n.language === "pa" ? "pa" : "en";

export function setAppLanguage(lng: "en" | "pa") {
  i18n.changeLanguage(lng);
  window.localStorage.setItem("bnt-lang", lng);
  document.documentElement.lang = lng;
}

export function tStatus(status: string, t: (key: string) => string): string {
  const map: Record<string, string> = {
    "Passed": "status_passed",
    "In Progress": "status_in_progress",
    "Pending": "status_pending",
    "Pending Review": "status_pending_review",
    "Approved": "status_approved",
    "Rejected": "status_rejected",
    "Active": "status_active",
    "Completed": "status_completed",
    "Maintenance Required": "status_maintenance",
    "Not Started": "status_not_started",
    "Resolved": "status_resolved",
    "Open": "status_open",
    "Expired": "status_expired",
    "Action Required": "status_action_required",
    "No Attempt": "status_no_attempt",
    "Overdue": "status_overdue",
    "Due today": "status_due_today",
    "Expiring Soon": "status_expiring_soon",
    "Compliant": "status_compliant",
    "Suspended": "status_suspended",
    "Under Review": "status_under_review"
  };
  return map[status] ? t(map[status]) : status;
}

export default i18n;
